-- ── CREATE INSTRUCTORS TABLE (not in migrations yet) ─────────────
create table if not exists instructors (
  id            uuid primary key default gen_random_uuid(),
  slug          text unique not null,
  name          text not null,
  role          text,
  subject       text,
  photo_url     text,
  initials      text,
  bio           text,
  rating        numeric(3,1),
  students      int,
  created_at    timestamptz default now()
);

create table if not exists instructor_universities (
  instructor_id uuid not null references instructors on delete cascade,
  university_id uuid not null references universities on delete cascade,
  primary key (instructor_id, university_id)
);

alter table instructors enable row level security;
alter table instructor_universities enable row level security;

do $$ begin
  if not exists (select 1 from pg_policies
                  where tablename = 'instructors'
                    and policyname = 'anyone reads instructors') then
    create policy "anyone reads instructors" on instructors for select using (true);
  end if;
end $$;

do $$ begin
  if not exists (select 1 from pg_policies
                  where tablename = 'instructor_universities'
                    and policyname = 'anyone reads instructor_universities') then
    create policy "anyone reads instructor_universities" on instructor_universities for select using (true);
  end if;
end $$;


